import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{R as n,m as r,t as i}from"./icons-DTR6_mEc.js";import{n as a,t as o}from"./ArticleLayout-oYmAtQSh.js";var s,c,l=e((()=>{i(),s=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Essayer un véhicule avant achat : qui assure l'essai routier ?`,description:`Avant d'acheter, vous voulez essayer le véhicule sur route ? En concession vous êtes souvent couvert, chez un particulier c'est plus risqué. Une assurance temporaire d'un jour sécurise l'essai. Attestation en 5 minutes.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-essai-vehicule-avant-achat`,datePublished:`2026-06-03`,dateModified:`2026-07-10`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Essayer un véhicule avant achat`,item:`https://assutempo.fr/articles/assurance-temporaire-essai-vehicule-avant-achat`}]},{"@context":`https://schema.org`,"@type":`HowTo`,name:`Comment souscrire une assurance pour un essai avant achat`,totalTime:`PT5M`,step:[{"@type":`HowToStep`,position:1,name:`Choisissez la durée (dès 1 jour)`,text:`Sélectionnez 1 jour pour un essai ponctuel, ou plus si vous enchaînez avec un achat.`},{"@type":`HowToStep`,position:2,name:`Renseignez le véhicule (carte grise)`,text:`Indiquez les informations du véhicule à partir de la carte grise du vendeur.`},{"@type":`HowToStep`,position:3,name:`Payez en ligne`,text:`Paiement sécurisé par carte bancaire, sans engagement.`},{"@type":`HowToStep`,position:4,name:`Recevez l'attestation (5 min)`,text:`Votre Mémo Véhicule Assuré et votre carte internationale d'assurance automobile arrivent par email.`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Faut-il une assurance pour essayer une voiture ?`,acceptedAnswer:{"@type":`Answer`,text:`Le véhicule doit avoir une RC. En concession, le pro couvre généralement ; chez un particulier, prévoyez une assurance temporaire pour ne pas engager le bonus-malus du vendeur.`}},{"@type":`Question`,name:`Suis-je couvert pour un essai en concession ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, généralement par l'assurance flotte du professionnel. Vérifiez la franchise en cas d'accident responsable.`}},{"@type":`Question`,name:`Et pour un essai chez un particulier ?`,acceptedAnswer:{"@type":`Answer`,text:`C'est un prêt de volant : couvert si le contrat du vendeur l'autorise, mais à son risque. Une assurance temporaire d'1 jour sécurise l'essai.`}},{"@type":`Question`,name:`Combien de temps souscrire ?`,acceptedAnswer:{"@type":`Answer`,text:`Dès 1 jour, jusqu'à 90 jours.`}},{"@type":`Question`,name:`Quels documents pour souscrire ?`,acceptedAnswer:{"@type":`Answer`,text:`Permis de l'essayeur, carte grise du véhicule, moyen de paiement.`}},{"@type":`Question`,name:`Reçoit-on une carte verte ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, elle a été supprimée en avril 2024. Vous recevez un Mémo Véhicule Assuré et une carte internationale d'assurance automobile (valable dans 34 pays) ; le contrôle se fait à la plaque via le FVA.`}}]}],c={slug:`assurance-temporaire-essai-vehicule-avant-achat`,seo:{title:`Essayer un véhicule avant achat : qui assure l'essai routier ?`,description:`Avant d'acheter, vous voulez essayer le véhicule sur route ? En concession vous êtes souvent couvert, chez un particulier c'est plus risqué. Une assurance temporaire d'un jour sécurise l'essai. Attestation en 5 minutes.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-essai-vehicule-avant-achat`,jsonLd:s},category:`Essai & achat`,readTime:`4 min`,updatedDate:`10 juillet 2026`,author:`Evidence Assurances`,headline:`Essayer un véhicule avant achat, bien assuré`,immediateAnswer:`Essayer un véhicule avant de l'acheter est vivement recommandé, mais qui assure l'essai ? En concession, vous êtes généralement couvert par le professionnel. Chez un particulier, c'est plus flou, et un accident peut coûter cher au vendeur. Une assurance temporaire d'un jour sécurise l'essai sans toucher au contrat de personne.`,answerCapsule:{answer:`En concession, l'assurance flotte du professionnel couvre généralement l'essai. Chez un particulier, c'est un prêt de volant : un accident responsable impacte le bonus-malus du vendeur. Une assurance temporaire d'un jour, à votre nom, sécurise l'essai sans toucher au contrat de personne.`,facts:[{anchor:`Art. L211-1`,text:`Tout véhicule essayé sur la voie publique doit avoir une responsabilité civile en cours, quel que soit le conducteur.`},{anchor:`Dès 1 jour`,text:`L'assurance temporaire se souscrit au jour près (jusqu'à 90 jours), attestation en 5 minutes, 100 % en ligne.`},{anchor:`Avril 2024`,text:`Plus de carte verte : la preuve d'assurance se fait à la plaque, via le Fichier des Véhicules Assurés (FVA).`}],updated:`10 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`Tout véhicule essayé sur la route doit avoir une RC en cours (art. L211-1), quel que soit le conducteur.`,`En concession/garage : l'assurance flotte du pro couvre généralement l'essai, vérifiez la franchise.`,`Chez un particulier : c'est un prêt de volant ; un accident responsable impacte le bonus-malus du vendeur. Une assurance temporaire d'1 jour protège les deux.`,`Attestation en 5 minutes, durée dès 1 jour.`]},{type:`decisionsplit`,question:`Ai-je besoin d'une assurance pour l'essai ?`,ariaLabel:`Schéma de décision : essai en concession (généralement couvert) vs essai chez un particulier (à sécuriser avec une assurance temporaire)`,voies:[{icon:n,titre:`Essai en concession / chez un pro`,verdict:`Généralement couvert par l'assurance du professionnel. Pas d'obligation de prendre la vôtre, vérifiez juste la franchise.`,statut:`ok`},{icon:r,titre:`Essai chez un particulier (ou prolongé)`,verdict:`Prêt de volant : un accident impacte le bonus-malus du vendeur. Une assurance temporaire d'1 jour à votre nom sécurise les deux.`,statut:`vigilance`}]},{type:`text`,heading:`Faut-il une assurance pour essayer une voiture ?`,paragraphs:[`Ça dépend du vendeur. La règle de base est claire : tout véhicule qui roule sur la voie publique doit avoir au moins une responsabilité civile (art. L211-1 du Code des assurances), quel que soit le conducteur. La vraie question, c'est de savoir QUI fournit cette assurance pendant l'essai.`],relatedLink:{text:`Contrôlé sans assurance : risques, amende et que faire`,href:`/articles/controle-sans-assurance-risques-amende`}},{type:`text`,heading:`Essai en concession ou chez un professionnel`,paragraphs:[`Les professionnels (concessionnaires, garages, mandataires) disposent d'une assurance flotte/garage qui couvre leurs véhicules de démonstration et d'essai. Vous êtes donc généralement couvert pendant l'essai, sans souscrire votre propre assurance. Deux réflexes quand même : demandez les conditions, et vérifiez la franchise en cas d'accident responsable, elle est souvent majorée pour un conducteur non désigné au contrat.`]},{type:`text`,heading:`Essai chez un particulier`,paragraphs:[`Là, pas de filet automatique. Le vendeur vous prête le volant : son assurance peut vous couvrir si son contrat l'autorise, mais un accident responsable impactera SON bonus-malus, et certains contrats restreignent le prêt. Pour ne pas faire peser ce risque sur le vendeur, et rassurer un vendeur méfiant, une assurance temporaire d'un jour à votre nom est la solution propre : vous essayez couvert, sans toucher au contrat du vendeur.`],relatedLink:{text:`Prêter ou emprunter un véhicule : roulez assuré`,href:`/articles/assurance-temporaire-pret-de-vehicule`}},{type:`text`,heading:`Combien de temps, et comment souscrire ?`,paragraphs:[`Dès 1 jour, au jour près (jusqu'à 90 jours si vous enchaînez essai et achat). Il vous faut le permis de l'essayeur, la carte grise du véhicule et un moyen de paiement. Attestation en 5 minutes, 100 % en ligne.`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`text`,heading:`Quels documents reçoit-on avec l'assurance ?`,paragraphs:[`Depuis avril 2024, la carte verte n'existe plus. En France, la preuve d'assurance se fait à la plaque, via le Fichier des Véhicules Assurés (FVA). Le contrat comprend le Mémo Véhicule Assuré et la carte internationale d'assurance automobile, valable dans les 34 pays.`]}],faqItems:[{q:`Faut-il une assurance pour essayer une voiture ?`,a:`Le véhicule doit avoir une RC. En concession, le pro couvre généralement ; chez un particulier, prévoyez une assurance temporaire pour ne pas engager le bonus-malus du vendeur.`},{q:`Suis-je couvert pour un essai en concession ?`,a:`Oui, généralement par l'assurance flotte du professionnel. Vérifiez la franchise en cas d'accident responsable.`},{q:`Et pour un essai chez un particulier ?`,a:`C'est un prêt de volant : couvert si le contrat du vendeur l'autorise, mais à son risque. Une assurance temporaire d'1 jour sécurise l'essai.`},{q:`Combien de temps souscrire ?`,a:`Dès 1 jour, jusqu'à 90 jours.`},{q:`Quels documents pour souscrire ?`,a:`Permis de l'essayeur, carte grise du véhicule, moyen de paiement.`},{q:`Reçoit-on une carte verte ?`,a:`Non, elle a été supprimée. Mémo Véhicule Assuré + carte internationale (34 pays) ; contrôle à la plaque via le FVA.`}]}}));function u(){return(0,d.jsx)(o,{data:c})}var d;e((()=>{a(),l(),d=t()}))();export{u as default};